import { test, expect } from '@playwright/test';

test.describe('Stale Record Conflict Error', () => {
  let testUrl: string;
  let recordId: string;
  let initialVersion: number;

  test.beforeEach(async ({ page }) => {
    testUrl = process.env.TEST_URL || 'http://localhost:3000';
    await page.goto(testUrl);

    // Create a test record
    const createResponse = await page.request.post(`${testUrl}/api/records`, {
      data: {
        title: 'Test Record',
        content: 'Initial content',
        version: 1
      }
    });

    const createdRecord = await createResponse.json();
    recordId = createdRecord.id;
    initialVersion = createdRecord.version;
  });

  test('should display conflict error when saving stale record', async ({ page }) => {
    await page.goto(`${testUrl}/records/${recordId}`);

    // Simulate another user updating the record
    await page.request.put(`${testUrl}/api/records/${recordId}`, {
      data: {
        title: 'Updated by another user',
        content: 'Modified content',
        version: initialVersion
      }
    });

    // Try to save with stale version
    const saveButton = page.getByRole('button', { name: /save/i });
    await saveButton.click();

    // Verify conflict error message appears
    const errorMessage = page.getByText(/conflict|stale|version mismatch/i);
    await expect(errorMessage).toBeVisible();
    await expect(errorMessage).toContainText(/conflict|stale|version mismatch/i);
  });

  test('should prevent save operation on stale record', async ({ page }) => {
    await page.goto(`${testUrl}/records/${recordId}`);

    // Update record externally to create stale state
    const externalUpdate = await page.request.put(`${testUrl}/api/records/${recordId}`, {
      data: {
        title: 'External update',
        content: 'Changed externally',
        version: initialVersion
      }
    });

    expect(externalUpdate.ok()).toBeTruthy();

    // Attempt to save with old version
    const titleInput = page.getByLabel(/title/i);
    await titleInput.fill('User attempted change');

    const saveButton = page.getByRole('button', { name: /save/i });
    const saveResponse = page.waitForResponse(
      response => response.url().includes(`/api/records/${recordId}`) && response.request().method() === 'PUT'
    );

    await saveButton.click();

    const response = await saveResponse;
    expect(response.status()).toBe(409); // Conflict status code

    const errorAlert = page.getByRole('alert');
    await expect(errorAlert).toBeVisible();
  });

  test('should allow retry after conflict error', async ({ page }) => {
    await page.goto(`${testUrl}/records/${recordId}`);

    // Create conflict scenario
    await page.request.put(`${testUrl}/api/records/${recordId}`, {
      data: {
        title: 'Another update',
        content: 'More changes',
        version: initialVersion
      }
    });

    // Attempt save that will fail
    const titleInput = page.getByLabel(/title/i);
    await titleInput.fill('First attempt');

    const saveButton = page.getByRole('button', { name: /save/i });
    await saveButton.click();

    // Verify error appears
    const errorMessage = page.getByText(/conflict|stale|version mismatch/i);
    await expect(errorMessage).toBeVisible();

    // Click retry or refresh button
    const retryButton = page.getByRole('button', { name: /retry|refresh/i });
    if (await retryButton.isVisible()) {
      await retryButton.click();

      // Verify page reloads with latest data
      await expect(page).toHaveURL(`${testUrl}/records/${recordId}`);
    }
  });
});
